function clone(value){ return JSON.parse(JSON.stringify(value)); }
function isoNow(){ return new Date().toISOString(); }
function dateOffset(days,hour=9,minute=30){const d=new Date();d.setDate(d.getDate()+days);d.setHours(hour,minute,0,0);return d.toISOString();}
function initialState(){
  return {
    users:clone(ACCOUNT_SEEDS),
    symptoms:[{id:1,patientId:1,content:'Mệt mỏi nhẹ (dữ liệu minh họa)',department:'Nội tổng quát',createdAt:isoNow()}],
    appointments:[{id:1,patientId:1,doctorId:3,department:'Nội tổng quát',at:dateOffset(3),reason:'Khám tổng quát (dữ liệu minh họa)',status:'Đã đặt',createdAt:isoNow()}],
    records:[{id:1,patientId:1,doctorId:3,appointmentId:1,symptoms:'Mệt mỏi nhẹ (dữ liệu minh họa)',diagnosis:'Hồ sơ minh họa — chưa phải chẩn đoán y khoa',plan:'Theo dõi sức khỏe và tái khám theo hướng dẫn của bác sĩ.',prescription:'Toa thuốc demo: không sử dụng như đơn thuốc thật.',createdAt:isoNow(),updatedAt:isoNow()}],
    clsOrders:[{id:1,recordId:1,patientId:1,doctorId:3,testName:'Xét nghiệm minh họa',notes:'Dữ liệu giả lập',result:null,resultBy:null,resultAt:null,createdAt:isoNow()}],
    reports:[],
    payments:[{id:1,patientId:1,appointmentId:1,description:'Phí khám minh họa',amount:200000,status:'Chưa thanh toán',method:'',createdAt:isoNow(),paidAt:null}],
    logs:[{id:1,actorId:2,action:'Khởi tạo dữ liệu demo',detail:'Dữ liệu minh họa được tạo trong trình duyệt',createdAt:isoNow()}],
    nextIds:{user:11,symptom:2,appointment:2,record:2,clsOrder:2,report:1,payment:2,log:2}
  };
}
function loadState(){
  try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){const parsed=JSON.parse(raw);if(parsed.users&&parsed.appointments&&parsed.records){parsed.users.forEach(u=>{if(u.role==='patient'&&typeof u.profile==='undefined')u.profile=null;});ACCOUNT_SEEDS.filter(seed=>['admin2','admin3'].includes(seed.username)).forEach(seed=>{if(!parsed.users.some(u=>u.username===seed.username))parsed.users.push(clone(seed));});parsed.nextIds=parsed.nextIds||{};parsed.nextIds.user=Math.max(Number(parsed.nextIds.user)||1,...parsed.users.map(u=>Number(u.id)+1));parsed.nextIds.symptom=parsed.nextIds.symptom||1;parsed.nextIds.appointment=parsed.nextIds.appointment||1;parsed.nextIds.record=parsed.nextIds.record||1;parsed.nextIds.clsOrder=parsed.nextIds.clsOrder||1;parsed.nextIds.report=parsed.nextIds.report||1;parsed.nextIds.payment=parsed.nextIds.payment||1;parsed.nextIds.log=parsed.nextIds.log||1;return parsed;}}}
  catch(e){console.warn('Không đọc được dữ liệu demo, tạo mới.',e);}
  const fresh=initialState();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(fresh));}catch(e){}return fresh;
}
function saveState(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){showToast('Trình duyệt không cho lưu dữ liệu. Hãy kiểm tra chế độ riêng tư.');}}
function nextId(type){const n=state.nextIds[type]||1;state.nextIds[type]=n+1;return n;}
function logAction(action,detail){state.logs.unshift({id:nextId('log'),actorId:currentUser?.id||null,action,detail,createdAt:isoNow()});saveState();}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function initials(name){return String(name||'TA').trim().split(/\s+/).slice(-2).map(x=>x[0]||'').join('').toUpperCase();}
function fmtDate(value,withTime=true){if(!value)return '—';const d=new Date(value);if(Number.isNaN(d.getTime()))return esc(value);return d.toLocaleString('vi-VN',withTime?{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}:{day:'2-digit',month:'2-digit',year:'numeric'});}
function money(value){return Number(value||0).toLocaleString('vi-VN')+' ₫';}
function statusClass(status){if(['Đã thanh toán','Đã hoàn tất','Đã xem bởi bác sĩ','Đã mở'].includes(status))return 'success';if(['Chưa thanh toán','Chờ bác sĩ phản hồi','Đã đặt','Chờ bảo hiểm'].includes(status))return 'warning';if(['Đã hủy','Đã khóa','Hỗ trợ tài chính'].includes(status))return 'danger';return 'neutral';}
function badge(status){return `<span class="badge ${statusClass(status)}">${esc(status)}</span>`;}
function personCell(name,sub=''){return `<div class="person-cell"><span class="person-dot">${esc(initials(name))}</span><span><strong>${esc(name)}</strong>${sub?`<small>${esc(sub)}</small>`:''}</span></div>`;}
function statCard(icon,label,value,note=''){return `<article class="stat-card"><div class="stat-top"><span>${esc(label)}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${esc(value)}</div><div class="stat-note">${esc(note)}</div></article>`;}
function panel(title,body,subtitle='',action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div><div class="panel-body">${body}</div></section>`;}
function table(headers,rows,empty='Chưa có dữ liệu.'){if(!rows.length)return `<div class="empty-state"><div class="empty-icon">▤</div>${empty}</div>`;return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function welcome(title,subtitle){return `<div class="welcome-row"><div><h2>${title}</h2><p>${subtitle}</p></div><div class="welcome-date">◷ &nbsp; ${new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'2-digit',month:'long',year:'numeric'})}</div></div>`;}
function activeUser(id){return state.users.find(u=>u.id===Number(id));}
function userName(id){return activeUser(id)?.name||'Không xác định';}
function userByRole(role){return state.users.filter(u=>u.role===role&&u.active);}
function patientName(id){return userName(id);}
function myAppointments(){return state.appointments.filter(a=>a.patientId===currentUser.id).sort((a,b)=>new Date(b.at)-new Date(a.at));}
function myRecords(){return state.records.filter(r=>r.patientId===currentUser.id).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));}
function navTo(page){if(currentUser?.role==='patient'&&!currentUser.profile&&page!=='profile'){showToast('Vui lòng hoàn tất hồ sơ bệnh nhân trước.');page='profile';}currentPage=page;renderPage();document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.getElementById('sidebar').classList.remove('open');document.getElementById('profile-menu').classList.add('hidden');}
function showToast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.add('hidden'),3600);}
function showNotice(message,type='info'){document.getElementById('notice-area').innerHTML=`<div class="notice ${type}">${esc(message)}</div>`;}
function clearNotice(){document.getElementById('notice-area').innerHTML='';}
function showModal(title,body,actions){document.getElementById('modal-title').textContent=title;document.getElementById('modal-body').innerHTML=body;document.getElementById('modal-actions').innerHTML=actions;document.getElementById('modal-backdrop').classList.remove('hidden');}
function closeModal(){document.getElementById('modal-backdrop').classList.add('hidden');}
function loginScreen(){document.getElementById('login-screen').classList.remove('hidden');document.getElementById('workspace').classList.add('hidden');document.getElementById('login-password').value='';document.getElementById('login-error').textContent='';}
function workspaceScreen(){document.getElementById('login-screen').classList.add('hidden');document.getElementById('workspace').classList.remove('hidden');document.getElementById('side-name').textContent=currentUser.name;document.getElementById('side-role').textContent=ROLE_LABELS[currentUser.role];document.getElementById('user-avatar').textContent=initials(currentUser.name);document.getElementById('top-avatar').textContent=initials(currentUser.name);document.getElementById('top-name').textContent=currentUser.name;document.getElementById('today-label').textContent=new Date().toLocaleDateString('vi-VN',{day:'2-digit',month:'short',year:'numeric'});document.getElementById('year-label').textContent=new Date().getFullYear();document.getElementById('side-nav').innerHTML=navByRole[currentUser.role].map(([page,icon,label])=>`<button class="nav-item ${page===currentPage?'active':''}" data-page="${page}"><span class="nav-icon">${icon}</span>${label}</button>`).join('');renderPage();}
function renderPage(){if(!currentUser)return;const root=document.getElementById('page-content');try{if(currentUser.role==='patient'&&!currentUser.profile&&currentPage!=='profile')currentPage='profile';clearNotice();const titles={profile:'Thông tin bệnh nhân',overview:'Tổng quan',appointments:currentUser.role==='patient'?'Lịch khám của tôi':'Lịch khám',records:currentUser.role==='patient'?'Hồ sơ sức khỏe':currentUser.role==='director'?'Quản lý bệnh án':'Hồ sơ bệnh án',payments:currentUser.role==='director'?'Lịch sử thanh toán':'Thanh toán',staff:'Quản lý tài khoản',logs:'Nhật ký & vận hành',cls:'Chỉ định cận lâm sàng',pharmacy:'Đơn thuốc & báo cáo',physio:'Kế hoạch điều trị',finance:'Quản lý tài chính',reports:'Báo cáo từ dược'};document.getElementById('page-title').textContent=titles[currentPage]||'Tổng quan';document.getElementById('top-eyebrow').textContent=(ROLE_LABELS[currentUser.role]||'Tài khoản').toUpperCase();const renderers={profile:renderPatientProfile,overview:renderOverview,appointments:renderAppointments,records:renderRecords,payments:renderPayments,staff:renderStaff,logs:renderLogs,cls:renderCLS,pharmacy:renderPharmacy,physio:renderPhysio,finance:renderFinance,reports:renderReports};root.innerHTML=(renderers[currentPage]||renderOverview)();if(!root.innerHTML.trim())root.innerHTML='<section class="panel"><h2>Chưa có nội dung</h2><p>Hãy chọn một mục ở menu bên trái.</p></section>';}catch(err){console.error('Lỗi hiển thị trang:',err);root.innerHTML='<section class="panel error-panel"><h2>Không tải được nội dung trang</h2><p>Hãy tải lại trang. Nếu lỗi vẫn còn, hãy mở bản ZIP mới và bảo đảm index.html, style.css, app.js nằm cùng thư mục.</p><details><summary>Chi tiết lỗi</summary><pre>'+esc(err&&err.message?err.message:String(err))+'</pre></details></section>';}}
function renderPatientProfile(){
 const p=currentUser.profile||{};
 return `${welcome('Cập nhật thông tin bệnh nhân','Vui lòng hoàn tất các trường bắt buộc trước khi sử dụng các chức năng khám bệnh.')}<div class="notice warning">Chỉ dùng dữ liệu giả lập khi thử nghiệm. Chức năng quét/xác thực CCCD và BHYT chưa kết nối cơ sở dữ liệu thật.</div>${panel('Hồ sơ bệnh nhân',`<form id="patient-profile-form" class="field-grid"><div class="field full"><label>Họ tên</label><input value="${esc(currentUser.name)}" disabled></div><div class="field"><label>Số điện thoại *</label><input name="phone" type="tel" required value="${esc(p.phone||currentUser.phone||'')}" placeholder="Số điện thoại demo"></div><div class="field"><label>CCCD *</label><input name="cccd" required value="${esc(p.cccd||'')}" placeholder="Số CCCD giả lập"><p class="helper-text">Quét mã và xác thực tự động chưa được tích hợp.</p></div><div class="field"><label>BHYT *</label><input name="bhyt" required value="${esc(p.bhyt||'')}" placeholder="Mã BHYT giả lập"><p class="helper-text">Quét mã BHYT chưa được tích hợp.</p></div><div class="field"><label>Ngày sinh *</label><input name="dob" type="date" required value="${esc(p.dob||'')}"></div><div class="field"><label>Giới tính *</label><select name="gender" required><option value="">Chọn giới tính</option><option ${p.gender==='Nam'?'selected':''}>Nam</option><option ${p.gender==='Nữ'?'selected':''}>Nữ</option><option ${p.gender==='Khác'?'selected':''}>Khác</option></select></div><div class="field"><label>Nơi thường trú *</label><input name="address" required value="${esc(p.address||'')}" placeholder="Nơi thường trú demo"></div><div class="field"><label>Chiều cao (m) *</label><input name="height" type="number" min="0.3" max="2.8" step="0.01" required value="${esc(p.height||'')}" placeholder="Ví dụ: 1.65"></div><div class="field"><label>Cân nặng (kg) *</label><input name="weight" type="number" min="1" max="400" step="0.1" required value="${esc(p.weight||'')}" placeholder="Ví dụ: 55"></div><div class="field full"><label>Dị ứng thực phẩm (không bắt buộc)</label><textarea name="foodAllergies" placeholder="Tên thực phẩm nếu có">${esc(p.foodAllergies||'')}</textarea></div><div class="field full"><label>Dị ứng thuốc (không bắt buộc)</label><textarea name="drugAllergies" placeholder="Tên thuốc/dược chất – nơi chẩn đoán, ví dụ giả lập">${esc(p.drugAllergies||'')}</textarea></div><div class="field full"><label>Tiền sử bệnh (không bắt buộc)</label><textarea name="history" placeholder="STT – bệnh – nơi chẩn đoán – thời gian khám">${esc(p.history||'')}</textarea></div><div class="field full"><div class="form-actions"><button class="btn btn-primary" type="submit">Lưu hồ sơ và tiếp tục</button></div></div></form>`,'Thông tin bắt buộc và thông tin tùy chọn')}`;
}
function renderOverview(){const role=currentUser.role;let html='';
 if(role==='patient'){
  const aps=myAppointments(), records=myRecords(), pays=state.payments.filter(p=>p.patientId===currentUser.id), symptom=state.symptoms.find(s=>s.patientId===currentUser.id);
  html+=welcome(`Xin chào, ${esc(currentUser.name.split(' ').slice(-2).join(' '))} 👋`,'Đây là không gian theo dõi lịch khám và hồ sơ sức khỏe demo của bạn.');
  html+=`<div class="stats-grid">${statCard('▦','Lịch khám',aps.filter(a=>a.status==='Đã đặt').length,'Lịch đang chờ khám')}${statCard('▤','Hồ sơ bệnh án',records.length,'Hồ sơ trong hệ thống demo')}${statCard('₫','Khoản chưa thanh toán',pays.filter(p=>p.status==='Chưa thanh toán').length,'Không phát sinh tiền thật')}${statCard('♡','Triệu chứng',''+(symptom?'Đã nhập':'Chưa nhập'),'Thông tin mô phỏng')}</div>`;
  html+=`<div class="notice warning">Đây là bản demo, không dùng để chẩn đoán hoặc thay thế tư vấn y tế. Nếu cần chăm sóc sức khỏe, hãy liên hệ nhân viên y tế phù hợp.</div>`;
  html+=`<div class="content-grid"><div>${panel('Lịch khám sắp tới',aps.filter(a=>a.status==='Đã đặt').slice(0,3).map(a=>`<div class="quick-item"><div class="quick-icon">▦</div><div><strong>${esc(a.department)}</strong><p>${fmtDate(a.at)} · ${esc(userName(a.doctorId))}</p><p>${esc(a.reason||'Không có ghi chú')}</p></div></div>`).join('')||'<div class="empty-state">Bạn chưa có lịch khám sắp tới.</div>','Theo dõi lịch hẹn gần nhất','<button class="btn btn-secondary btn-small" data-page="appointments">Xem lịch</button>')}
  ${panel('Hồ sơ sức khỏe gần đây',records.slice(0,2).map(r=>`<div class="record-card"><div class="record-card-top"><div><h3>${esc(r.diagnosis)}</h3><div class="record-meta">${fmtDate(r.createdAt)} · ${esc(userName(r.doctorId))}</div></div>${badge('Hồ sơ demo')}</div><p>${esc(r.plan||'Chưa có kế hoạch điều trị.')}</p></div>`).join('')||'<div class="empty-state">Chưa có hồ sơ bệnh án.</div>','Thông tin được nhập bởi bác sĩ','<button class="btn btn-secondary btn-small" data-page="records">Mở hồ sơ</button>')}</div><div>${panel('Lối tắt',`<div class="quick-list"><div class="quick-item"><div class="quick-icon">＋</div><div><strong>Đặt lịch khám</strong><p>Tạo yêu cầu lịch khám demo với bác sĩ.</p><button class="btn btn-secondary btn-small" data-page="appointments">Đặt lịch</button></div></div><div class="quick-item"><div class="quick-icon">♡</div><div><strong>Thông tin triệu chứng</strong><p>${symptom?'Đã ghi nhận một lần.':'Bạn có thể ghi triệu chứng một lần trong demo.'}</p><button class="btn btn-secondary btn-small" data-page="records">Xem hồ sơ</button></div></div><div class="quick-item"><div class="quick-icon">₫</div><div><strong>Thanh toán</strong><p>Xem trạng thái các khoản thu mô phỏng.</p><button class="btn btn-secondary btn-small" data-page="payments">Mở thanh toán</button></div></div></div>`,'Thao tác nhanh')}</div></div>`;
 } else if(role==='director'){
  html+=welcome('Tổng quan quản lý','Theo dõi hoạt động demo, tài khoản và hồ sơ bệnh án trong phạm vi phân quyền.');
  html+=`<div class="stats-grid">${statCard('♙','Tài khoản',state.users.length,'Tất cả vai trò')}${statCard('▦','Lịch khám',state.appointments.length,'Lịch trong hệ thống')}${statCard('▤','Bệnh án',state.records.length,'Hồ sơ đã tạo')}${statCard('₫','Khoản thu',state.payments.length,'Khoản tài chính demo')}</div>`;
  html+=`<div class="content-grid"><div>${panel('Hoạt động gần đây',table(['NGƯỜI THỰC HIỆN','HOẠT ĐỘNG','THỜI GIAN'],state.logs.slice(0,6).map(l=>`<tr><td>${esc(userName(l.actorId))}</td><td><strong>${esc(l.action)}</strong><div class="subline">${esc(l.detail)}</div></td><td>${fmtDate(l.createdAt)}</td></tr>`),'Chưa có nhật ký'), 'Nhật ký hệ thống')}${panel('Bệnh án mới nhất',table(['BỆNH NHÂN','CHẨN ĐOÁN / GHI CHÚ','NGÀY TẠO'],state.records.slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,5).map(r=>`<tr><td>${personCell(patientName(r.patientId),'ID #'+r.patientId)}</td><td>${esc(r.diagnosis)}</td><td>${fmtDate(r.createdAt)}</td></tr>`)),'Các hồ sơ demo gần đây')}</div><div>${panel('Trung tâm quản lý',`<div class="quick-list"><div class="quick-item"><div class="quick-icon">♙</div><div><strong>Tài khoản nhân sự</strong><p>Khóa hoặc mở tài khoản demo.</p><button class="btn btn-secondary btn-small" data-page="staff">Quản lý tài khoản</button></div></div><div class="quick-item"><div class="quick-icon">▤</div><div><strong>Kiểm tra bệnh án</strong><p>Quy tắc demo cho phép sửa trong 24 giờ sau khi tạo.</p><button class="btn btn-secondary btn-small" data-page="records">Xem bệnh án</button></div></div><div class="quick-item"><div class="quick-icon">◷</div><div><strong>Nhật ký hoạt động</strong><p>Theo dõi thao tác đã mô phỏng.</p><button class="btn btn-secondary btn-small" data-page="logs">Mở nhật ký</button></div></div></div>`,'Các chức năng chính')}${panel('Lưu ý quyền truy cập','<p class="muted">Giám đốc được xem và chỉnh sửa hồ sơ trong vòng 24 giờ theo quy tắc demo. Mọi thay đổi sẽ được ghi vào nhật ký.</p>')}</div></div>`;
 } else if(role==='doctor'){
  const myA=state.appointments.filter(a=>a.doctorId===currentUser.id&&a.status==='Đã đặt');const reports=state.reports.filter(r=>r.status!=='Đã xem bởi bác sĩ');
  html+=welcome('Xin chào, bác sĩ','Quản lý lịch khám, tạo hồ sơ bệnh án và theo dõi báo cáo từ bộ phận dược.');html+=`<div class="stats-grid">${statCard('▦','Lịch đang chờ',myA.length,'Lịch được giao')}${statCard('♙','Bệnh nhân',state.users.filter(u=>u.role==='patient'&&u.active).length,'Tài khoản bệnh nhân hoạt động')}${statCard('▤','Hồ sơ đã tạo',state.records.filter(r=>r.doctorId===currentUser.id).length,'Hồ sơ của bác sĩ')}${statCard('⚑','Báo cáo dược',reports.length,'Chưa đánh dấu đã xem')}</div>`;
  html+=`<div class="content-grid"><div>${panel('Lịch khám sắp tới',table(['BỆNH NHÂN','KHOA / LÝ DO','THỜI GIAN','TRẠNG THÁI'],myA.slice(0,5).map(a=>`<tr><td>${personCell(patientName(a.patientId))}</td><td>${esc(a.department)}<div class="subline">${esc(a.reason)}</div></td><td>${fmtDate(a.at)}</td><td>${badge(a.status)}</td></tr>`),'Chưa có lịch khám') ,'Lịch làm việc')}${panel('Báo cáo dược cần xem',reports.slice(0,4).map(r=>`<div class="quick-item"><div class="quick-icon">⚑</div><div><strong>Bệnh án #${r.recordId} · ${esc(patientName(state.records.find(x=>x.id===r.recordId)?.patientId))}</strong><p>${esc(r.message)}</p><button class="btn btn-secondary btn-small" data-resolve-report="${r.id}">Đánh dấu đã xem</button></div></div>`).join('')||'<div class="empty-state">Không có báo cáo chờ xử lý.</div>','Trao đổi liên chuyên môn')}</div><div>${panel('Tạo hồ sơ bệnh án',doctorRecordForm(),'Ghi nhận sau khi khám')}</div></div>`;
 } else if(role==='cls'){
  const orders=state.clsOrders;html+=welcome('Bộ phận cận lâm sàng','Tiếp nhận chỉ định từ bác sĩ và gửi kết quả một lần trong bản demo.');html+=`<div class="stats-grid">${statCard('⌕','Tổng chỉ định',orders.length,'Tất cả hồ sơ')}${statCard('◷','Chờ kết quả',orders.filter(o=>!o.result).length,'Chưa nhập kết quả')}${statCard('✓','Đã hoàn tất',orders.filter(o=>o.result).length,'Kết quả đã gửi')}${statCard('♙','Bệnh nhân',new Set(orders.map(o=>o.patientId)).size,'Có chỉ định')}</div>`;html+=panel('Danh sách chỉ định',clsTable(orders),'Sau khi gửi kết quả, tài khoản CLS không thể chỉnh sửa hoặc gửi lại.');
 } else if(role==='pharmacist'){
  const recs=state.records.filter(r=>r.prescription);html+=welcome('Nghiệp vụ dược','Kiểm tra đơn thuốc trong hồ sơ demo và báo cáo vấn đề cho bác sĩ điều trị.');html+=`<div class="stats-grid">${statCard('⚕','Đơn thuốc',recs.length,'Hồ sơ có ghi toa')}${statCard('⚑','Báo cáo đã gửi',state.reports.length,'Báo cáo trong hệ thống')}${statCard('◷','Chờ phản hồi',state.reports.filter(r=>r.status==='Chờ bác sĩ phản hồi').length,'Chưa được bác sĩ đánh dấu')}${statCard('♙','Bệnh nhân',new Set(recs.map(r=>r.patientId)).size,'Hồ sơ liên quan')}</div>`;html+=panel('Đơn thuốc / báo cáo vấn đề',pharmacyTable(recs),'Chỉ dùng thông tin giả lập; không sử dụng toa thuốc demo để điều trị.');
 } else if(role==='physio'){
  const recs=state.records.filter(r=>r.plan);html+=welcome('Kế hoạch vật lý trị liệu','Xem hồ sơ có kế hoạch điều trị do bác sĩ ghi nhận.');html+=`<div class="stats-grid">${statCard('♧','Kế hoạch',recs.length,'Hồ sơ có nội dung điều trị')}${statCard('♙','Bệnh nhân',new Set(recs.map(r=>r.patientId)).size,'Hồ sơ liên quan')}${statCard('◷','Cập nhật gần đây',recs.length?fmtDate(recs[0].updatedAt,false):'—','Dữ liệu demo')}${statCard('▤','Quyền truy cập','Chỉ xem','Không sửa bệnh án')}</div>`;html+=panel('Hồ sơ có kế hoạch điều trị',recs.map(r=>`<div class="record-card"><div class="record-card-top"><div><h3>${esc(patientName(r.patientId))} · Bệnh án #${r.id}</h3><div class="record-meta">Bác sĩ: ${esc(userName(r.doctorId))} · ${fmtDate(r.updatedAt)}</div></div>${badge('Chỉ xem')}</div><p><strong>Chẩn đoán ghi trong demo:</strong> ${esc(r.diagnosis)}</p><p><strong>Kế hoạch:</strong> ${esc(r.plan)}</p></div>`).join('')||'<div class="empty-state">Chưa có kế hoạch điều trị.</div>','Chỉ xem thông tin cần thiết');
 } else if(role==='finance'){
  const paid=state.payments.filter(p=>p.status==='Đã thanh toán').reduce((s,p)=>s+p.amount,0),unpaid=state.payments.filter(p=>p.status==='Chưa thanh toán').reduce((s,p)=>s+p.amount,0);html+=welcome('Tổng quan tài chính','Theo dõi các khoản thu demo, cập nhật trạng thái thanh toán và hỗ trợ.');html+=`<div class="stats-grid">${statCard('₫','Tổng đã thanh toán',money(paid),'Giao dịch demo')}${statCard('◷','Chưa thanh toán',money(unpaid),'Không phải khoản thu thật')}${statCard('▤','Tổng khoản thu',state.payments.length,'Các khoản trong hệ thống')}${statCard('♡','Bảo hiểm / hỗ trợ',state.payments.filter(p=>['Chờ bảo hiểm','Hỗ trợ tài chính'].includes(p.status)).length,'Khoản cần theo dõi')}</div>`;html+=panel('Các khoản thu gần đây',financeTable(state.payments.slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))),'Cập nhật trạng thái tài chính cho mục đích minh họa.');
 } else if(role==='tech'){
  html+=welcome('Vận hành hệ thống','Theo dõi tài khoản và nhật ký kỹ thuật. Vai trò TECH không được xem hồ sơ bệnh án.');html+=`<div class="stats-grid">${statCard('⚙','Tài khoản',state.users.length,'Tất cả vai trò')}${statCard('▦','Lịch khám',state.appointments.length,'Số lịch demo')}${statCard('◷','Nhật ký',state.logs.length,'Hoạt động được ghi nhận')}${statCard('▤','Bệnh án','Đã hạn chế','Không hiển thị dữ liệu y tế')}</div>`;html+=`<div class="content-grid"><div>${panel('Nhật ký hệ thống',logsTable(state.logs.slice(0,10)),'Hoạt động mới nhất')}${panel('Tài khoản hệ thống',table(['TÀI KHOẢN','VAI TRÒ','TRẠNG THÁI'],state.users.map(u=>`<tr><td>${personCell(u.name,u.username)}</td><td>${esc(ROLE_LABELS[u.role])}</td><td>${badge(u.active?'Đang hoạt động':'Đã khóa')}</td></tr>`)),'Không hiển thị hồ sơ bệnh án')}</div><div>${panel('Trạng thái demo','<div class="quick-list"><div class="quick-item"><div class="quick-icon">✓</div><div><strong>Lưu trữ cục bộ</strong><p>Dữ liệu được lưu trong localStorage của trình duyệt.</p></div></div><div class="quick-item"><div class="quick-icon">⌕</div><div><strong>Phân quyền giao diện</strong><p>Menu được lọc theo vai trò tài khoản.</p></div></div></div>')}<div class="security-note">Đây không phải hệ thống xác thực an toàn. Không triển khai công khai, không lưu dữ liệu cá nhân hoặc y tế thật.</div></div></div>`;
 }
 return html;
}
function doctorRecordForm(){const patients=userByRole('patient');const appts=state.appointments.filter(a=>a.doctorId===currentUser.id&&a.status==='Đã đặt');return `<form id="record-form" class="field-grid"><div class="field full"><label>Bệnh nhân *</label><select name="patientId" required>${patients.map(p=>`<option value="${p.id}">${esc(p.name)} (${esc(p.username)})</option>`).join('')}</select></div><div class="field full"><label>Lịch khám liên quan</label><select name="appointmentId"><option value="">Không chọn</option>${appts.map(a=>`<option value="${a.id}">#${a.id} · ${esc(patientName(a.patientId))} · ${fmtDate(a.at)}</option>`).join('')}</select></div><div class="field full"><label>TCCN – Triệu chứng cơ năng</label><textarea name="symptoms" placeholder="Thông tin triệu chứng bệnh nhân cung cấp (giả lập)"></textarea></div><div class="field full"><label>TCTT – Triệu chứng thực thể</label><textarea name="physicalSigns" placeholder="Ghi nhận khám lâm sàng (giả lập)"></textarea></div><div class="field full"><label>Chẩn đoán sơ bộ</label><textarea name="preliminaryDiagnosis" placeholder="Chẩn đoán sơ bộ trong demo"></textarea></div><div class="field full"><label>Đề nghị cận lâm sàng (nếu có)</label><input name="testName" placeholder="Ví dụ: Xét nghiệm minh họa / chẩn đoán hình ảnh"><input name="testNotes" placeholder="Ghi chú chỉ định" style="margin-top:8px"></div><div class="field full"><label>Chẩn đoán xác định *</label><textarea name="diagnosis" required placeholder="Chẩn đoán xác định ghi trong hồ sơ demo"></textarea></div><div class="field full"><label>Điều trị</label><select name="treatmentType"><option value="medicine">Điều trị có dùng thuốc</option><option value="non_medicine">Điều trị không dùng thuốc</option></select></div><div class="field full"><label>Kế hoạch điều trị</label><textarea name="plan" placeholder="Kế hoạch minh họa..."></textarea></div><div class="field full"><label>Toa thuốc (nếu có)</label><textarea name="prescription" placeholder="Không nhập toa thuốc thật"></textarea></div><div class="field"><label>Ngày tái khám</label><input name="followUpDate" type="date"></div><div class="field full"><p class="helper-text">Dùng dữ liệu giả lập. Nội dung không phải tư vấn, chẩn đoán hay chỉ định y khoa thực tế.</p></div><div class="field full"><div class="form-actions"><button type="reset" class="btn btn-outline">Xóa nội dung</button><button type="submit" class="btn btn-primary">Lưu hồ sơ demo</button></div></div></form>`;}
function appointmentCalendar(){const now=new Date(),year=now.getFullYear(),month=now.getMonth(),first=new Date(year,month,1),days=new Date(year,month+1,0).getDate(),offset=(first.getDay()+6)%7;const booked=new Map();myAppointments().filter(a=>a.status==='Đã đặt').forEach(a=>{const d=new Date(a.at);if(d.getFullYear()===year&&d.getMonth()===month){const day=d.getDate();if(!booked.has(day))booked.set(day,[]);booked.get(day).push(a);}});const cells=[];for(let i=0;i<offset;i++)cells.push('<div class="calendar-day empty"></div>');for(let day=1;day<=days;day++){const ap=booked.get(day)||[];cells.push(`<div class="calendar-day ${ap.length?'has-appointment':''}"><strong>${day}</strong>${ap.map(a=>`<small>${new Date(a.at).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})} · ${esc(a.department)}</small>`).join('')}</div>`);}return `<div class="calendar-grid">${['Thứ 2','Thứ 3','Thứ 4','Thứ 5','Thứ 6','Thứ 7','CN'].map(d=>`<div class="calendar-weekday">${d}</div>`).join('')}${cells.join('')}</div>`;}
function renderAppointments(){if(currentUser.role==='patient'){
 if(!visitMode) return `${welcome('Bạn muốn khám bệnh như thế nào?','Chọn một quy trình để tiếp tục đặt lịch khám.')}<div class="content-grid"><div>${panel('Khám bệnh mới',`<p>Bắt đầu từ triệu chứng cơ năng, nhận gợi ý khoa khám và chọn lịch hẹn phù hợp.</p><button class="btn btn-primary" data-visit-mode="new">Bắt đầu khám bệnh mới →</button>`,'Dành cho lượt khám mới')}</div><div>${panel('Tái khám',`<p>Ghi lại tình trạng cần tái khám và các triệu chứng mới nếu có, sau đó chọn lịch.</p><button class="btn btn-secondary" data-visit-mode="revisit">Tiếp tục tái khám →</button>`,'Dành cho người đã từng khám')}</div></div>${panel('Lịch tháng này',appointmentCalendar(),'Ngày có lịch được tô đậm')}${panel('Danh sách lịch khám của tôi',table(['KHOA / BÁC SĨ','THỜI GIAN','LÝ DO','TRẠNG THÁI'],myAppointments().map(a=>`<tr><td><strong>${esc(a.department)}</strong><div class="subline">${esc(userName(a.doctorId))}</div></td><td>${fmtDate(a.at)}</td><td>${esc(a.reason||'—')}</td><td>${badge(a.status)}</td></tr>`),'Bạn chưa có lịch khám.'))}`;
 const aps=myAppointments();return `${welcome(visitMode==='revisit'?'Quy trình tái khám':'Quy trình khám bệnh mới','Nhập triệu chứng giả lập; hệ thống gợi ý khoa để bạn tự chọn trước khi đặt lịch.')}<div class="content-grid"><div>${panel('Lịch khám của tôi',table(['KHOA / BÁC SĨ','THỜI GIAN','LÝ DO','TRẠNG THÁI','THAO TÁC'],aps.map(a=>`<tr><td><strong>${esc(a.department)}</strong><div class="subline">${esc(userName(a.doctorId))}</div></td><td>${fmtDate(a.at)}</td><td>${esc(a.reason||'—')}</td><td>${badge(a.status)}</td><td>${a.status==='Đã đặt'?`<button class="btn btn-danger btn-small" data-cancel-appt="${a.id}">Hủy lịch</button>`:'—'}</td></tr>`),'Bạn chưa có lịch khám.') ,'Lịch hẹn')}</div><div>${panel('Chatbox tiếp nhận triệu chứng',bookingForm()+'<button type="button" class="btn btn-outline" data-export-symptoms>Xuất phiếu triệu chứng PDF</button>','Gợi ý khoa bằng từ khóa demo; có thể lưu phiếu qua hộp thoại in') }<div class="security-note">Nếu có triệu chứng nghiêm trọng hoặc cần trợ giúp khẩn cấp, hãy liên hệ cơ sở y tế phù hợp; gợi ý tự động không thay thế đánh giá của nhân viên y tế.</div><button class="btn btn-outline" data-visit-mode="">← Quay lại chọn quy trình</button></div></div>`;
 }
 const aps=state.appointments.filter(a=>currentUser.role==='doctor'?a.doctorId===currentUser.id:true).sort((a,b)=>new Date(a.at)-new Date(b.at));return `${welcome('Quản lý lịch khám','Theo dõi lịch hẹn được phân công và cập nhật trạng thái sau buổi khám.')} ${panel('Danh sách lịch khám',table(['BỆNH NHÂN','KHOA / LÝ DO','THỜI GIAN','TRẠNG THÁI','THAO TÁC'],aps.map(a=>`<tr><td>${personCell(patientName(a.patientId))}</td><td>${esc(a.department)}<div class="subline">${esc(a.reason||'—')}</div><div class="subline">${esc(a.location||'Phòng khám Tâm An')}</div></td><td>${fmtDate(a.at)}</td><td>${badge(a.status)}</td><td>${a.status==='Đã đặt'?`<div class="inline-actions"><button class="btn btn-outline btn-small" data-appt-action="complete" data-id="${a.id}">Hoàn tất</button><button class="btn btn-danger btn-small" data-appt-action="cancel" data-id="${a.id}">Hủy</button></div>`:'—'}</td></tr>`)),'Chưa có lịch khám')}`;
}
function bookingForm(){const doctors=userByRole('doctor');const minDate=new Date(Date.now()+86400000).toISOString().slice(0,16);return `<form id="booking-form" class="field-grid"><input type="hidden" name="visitType" value="${visitMode||'new'}"><div class="field full"><label>Chatbox – triệu chứng cơ năng *</label><textarea name="symptoms" required placeholder="Mô tả triệu chứng giả lập${visitMode==='revisit'?' và triệu chứng mới (nếu có)':''}"></textarea><p class="helper-text">Sau khi nhập, hệ thống sẽ gợi ý khoa để bạn cân nhắc. Đây không phải chẩn đoán.</p></div><div class="field full"><label>Khoa khám *</label><select name="department" id="booking-department"><option>Nội tổng quát</option><option>Tim mạch</option><option>Tai Mũi Họng</option><option>Tiêu hóa</option><option>Cơ xương khớp</option><option>Da liễu</option><option>Chẩn đoán hình ảnh</option><option>Vật lý trị liệu</option></select><p id="department-suggestion" class="helper-text">Nhập triệu chứng để xem gợi ý khoa.</p></div><div class="field full"><label>Bác sĩ *</label><select name="doctorId" required>${doctors.map(d=>`<option value="${d.id}">${esc(d.name)} · ${esc(d.department)}</option>`).join('')}</select></div><div class="field full"><label>Ngày giờ khám *</label><input type="datetime-local" name="at" min="${minDate}" required></div><div class="field full"><label>Địa điểm khám *</label><input name="location" required value="Phòng khám Tâm An - cơ sở chính"></div><div class="field full"><label>Ghi chú thêm (không bắt buộc)</label><textarea name="reason" placeholder="Thông tin giả lập"></textarea></div><div class="field full"><div class="form-actions"><button class="btn btn-primary" type="submit">Lưu triệu chứng và đặt lịch</button></div></div></form>`;}
function renderRecords(){
 if(currentUser.role==='patient'){
  const records=myRecords();
  const symptom=state.symptoms.find(s=>s.patientId===currentUser.id);
  const orders=state.clsOrders.filter(o=>o.patientId===currentUser.id);
  const recordCards=records.map(r=>`<div class="record-card"><div class="record-card-top"><div><h3>${esc(r.diagnosis)}</h3><div class="record-meta">${fmtDate(r.createdAt)} · ${esc(userName(r.doctorId))}</div></div>${badge('Bệnh án')}</div>${r.symptoms?`<p><strong>Ghi nhận:</strong> ${esc(r.symptoms)}</p>`:''}${r.plan?`<p><strong>Kế hoạch:</strong> ${esc(r.plan)}</p>`:''}${r.prescription?`<p><strong>Toa thuốc demo:</strong> ${esc(r.prescription)}</p>`:''}</div>`).join('')||'<div class="empty-state">Chưa có bệnh án.</div>';
  const orderCards=orders.map(o=>`<div class="record-card"><div class="record-card-top"><div><h3>${esc(o.testName)}</h3><div class="record-meta">Chỉ định #${o.id} · ${fmtDate(o.createdAt)}</div></div>${badge(o.result?'Đã có kết quả':'Đang chờ')}</div><p>${o.result?esc(o.result):'Chưa có kết quả được bộ phận CLS gửi.'}</p>${o.result?`<div class="record-meta">Gửi lúc ${fmtDate(o.resultAt)}</div>`:''}</div>`).join('')||'<div class="empty-state">Chưa có chỉ định CLS.</div>';
  const symptomContent=symptom?`<div class="record-card"><div class="record-meta">Đã ghi nhận ${fmtDate(symptom.createdAt)}</div><p>${esc(symptom.content)}</p><div class="divider"></div><p><strong>Khoa gợi ý trong demo:</strong> ${esc(symptom.department)}</p></div><p class="helper-text">Gợi ý bằng từ khóa đơn giản, không phải phân loại y khoa.</p>`:symptomForm();
  const prof=currentUser.profile||{};const profileSummary=`<div class="quick-list"><div class="quick-item"><div><strong>${esc(currentUser.name)}</strong><p>SĐT: ${esc(prof.phone||'—')} · CCCD: ${esc(prof.cccd||'—')}</p><p>BHYT: ${esc(prof.bhyt||'—')} · Ngày sinh: ${esc(prof.dob||'—')} · Giới tính: ${esc(prof.gender||'—')}</p><p>Thường trú: ${esc(prof.address||'—')} · Chiều cao: ${esc(prof.height||'—')} m · Cân nặng: ${esc(prof.weight||'—')} kg</p><p>Dị ứng thực phẩm: ${esc(prof.foodAllergies||'Không khai báo')} · Dị ứng thuốc: ${esc(prof.drugAllergies||'Không khai báo')}</p><p>Tiền sử bệnh: ${esc(prof.history||'Không khai báo')}</p></div></div></div>`;return `${welcome('Hồ sơ sức khỏe','Xem thông tin cá nhân, chẩn đoán, toa thuốc, kết quả cận lâm sàng và ngày tái khám.')}<div class="notice warning">Các hồ sơ dưới đây là dữ liệu giả lập để thử giao diện, không phải hồ sơ y tế thật hoặc lời khuyên điều trị.</div>${panel('Thông tin hồ sơ bệnh nhân',profileSummary,'Thông tin đã được bệnh nhân khai báo') }<div class="content-grid"><div>${panel('Bệnh án của tôi',recordCards,'Hồ sơ chỉ hiển thị cho tài khoản bệnh nhân hiện tại')}${panel('Kết quả cận lâm sàng',orderCards)}</div><div>${panel('Thông tin triệu chứng',symptomContent,'Chỉ nhập một lần trong demo')}${panel('Tóm tắt tài khoản',`<div class="quick-list"><div class="quick-item"><div class="quick-icon">♙</div><div><strong>${esc(currentUser.name)}</strong><p>Tài khoản: ${esc(currentUser.username)}</p></div></div><div class="quick-item"><div class="quick-icon">▤</div><div><strong>${records.length} bệnh án</strong><p>Hồ sơ hiển thị từ dữ liệu demo.</p></div></div></div>`)}</div></div>`;
 }
 const records=state.records.slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
 if(currentUser.role==='doctor'){
  const cards=records.map(r=>`<div class="record-card"><div class="record-card-top"><div><h3>${esc(patientName(r.patientId))} · Bệnh án #${r.id}</h3><div class="record-meta">Bác sĩ: ${esc(userName(r.doctorId))} · ${fmtDate(r.createdAt)}</div></div>${badge('Bệnh án')}</div><p><strong>Chẩn đoán:</strong> ${esc(r.diagnosis)}</p><p><strong>TCCN:</strong> ${esc(r.symptoms||'—')}</p><p><strong>TCTT:</strong> ${esc(r.physicalSigns||'—')}</p><p><strong>Chẩn đoán sơ bộ:</strong> ${esc(r.preliminaryDiagnosis||'—')}</p><p><strong>Kế hoạch:</strong> ${esc(r.plan||'—')}</p><p><strong>Điều trị:</strong> ${r.treatmentType==='non_medicine'?'Không dùng thuốc':'Có dùng thuốc'}</p><p><strong>Toa thuốc demo:</strong> ${esc(r.prescription||'—')}</p><p><strong>Ngày tái khám:</strong> ${esc(r.followUpDate||'—')}</p></div>`).join('')||'<div class="empty-state">Chưa có bệnh án.</div>';
  return `${welcome('Quản lý bệnh án','Xem hồ sơ demo và tạo bệnh án theo vai trò bác sĩ.')}<div class="content-grid"><div>${panel('Danh sách bệnh án',cards,'Hồ sơ được tạo trong demo')}</div><div>${panel('Tạo bệnh án mới',doctorRecordForm(),'Thông tin giả lập')}</div></div>`;
 }
 const rows=records.map(r=>{const allowed=(Date.now()-new Date(r.createdAt).getTime())<=24*60*60*1000;return `<tr><td>#${r.id}</td><td>${personCell(patientName(r.patientId))}</td><td>${esc(userName(r.doctorId))}</td><td><strong>${esc(r.diagnosis)}</strong><div class="subline">${esc(r.plan||'Không có kế hoạch')}</div></td><td>${fmtDate(r.createdAt)}</td><td>${allowed?`<button class="btn btn-secondary btn-small" data-edit-record="${r.id}">Chỉnh sửa</button>`:badge('Quá 24 giờ')}</td></tr>`;});
 return `${welcome('Quản lý bệnh án','Giám đốc có thể xem hồ sơ demo và chỉnh sửa trong vòng 24 giờ kể từ lúc tạo.')} ${panel('Danh sách bệnh án',table(['MÃ HỒ SƠ','BỆNH NHÂN','BÁC SĨ','CHẨN ĐOÁN / GHI CHÚ','NGÀY TẠO','THAO TÁC'],rows,'Chưa có hồ sơ'),'Quy tắc chỉnh sửa trong 24 giờ')}`;
}
function symptomForm(){return `<form id="symptom-form" class="field-grid"><div class="field full"><label>Triệu chứng / ghi nhận *</label><textarea name="content" required placeholder="Chỉ nhập thông tin giả lập"></textarea><p class="helper-text">Thông tin được ghi nhận một lần trong demo. Không nhập dữ liệu sức khỏe cá nhân thật.</p></div><div class="field full"><div class="form-actions"><button class="btn btn-primary" type="submit">Lưu triệu chứng</button></div></div></form>`;}
function renderPayments(){const isAdmin=currentUser.role==='director';const pays=state.payments.filter(p=>isAdmin||p.patientId===currentUser.id).slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));const total=pays.reduce((s,p)=>s+Number(p.amount||0),0),insurance=pays.reduce((s,p)=>s+Number(p.insuranceCoverage||0),0),due=pays.reduce((s,p)=>s+Number(p.patientDue??Math.max(0,(p.amount||0)-(p.insuranceCoverage||0))),0);return `${welcome(isAdmin?'Lịch sử thanh toán toàn hệ thống':'Thanh toán của tôi',isAdmin?'Admin xem được lịch sử các khoản thanh toán trong hệ thống demo.':'Xem chi tiết khoản phí, phần BHYT mô phỏng chi trả và số tiền bệnh nhân cần trả.')}<div class="stats-grid">${statCard('₫','Tổng chi phí',money(total),'Khoản mô phỏng')}${statCard('♡','BHYT chi trả',money(insurance),'Tỷ lệ minh họa')}${statCard('₫','Bệnh nhân cần trả',money(due),'Không phát sinh tiền thật')}${statCard('◷','Chưa thanh toán',pays.filter(p=>p.status==='Chưa thanh toán').length,'Giao dịch demo')}</div>${panel(isAdmin?'Lịch sử thanh toán':'Chi tiết thanh toán',table([...(isAdmin?['BỆNH NHÂN']:[]),'KHOẢN THU','SỐ LƯỢNG','ĐƠN GIÁ','THÀNH TIỀN','BHYT CHI TRẢ','BỆNH NHÂN TRẢ','TRẠNG THÁI','MÃ / THAO TÁC'],pays.map(p=>{const ins=Number(p.insuranceCoverage||0),patientDue=Number(p.patientDue??Math.max(0,p.amount-ins));return `<tr>${isAdmin?`<td><strong>${esc(patientName(p.patientId))}</strong><div class="subline">${esc(activeUser(p.patientId)?.email||'')}</div></td>`:''}<td><strong>${esc(p.description)}</strong><div class="subline">Tạo lúc ${fmtDate(p.createdAt)}</div></td><td>1</td><td>${money(p.amount)}</td><td><strong>${money(p.amount)}</strong></td><td>${money(ins)}</td><td><strong>${money(patientDue)}</strong></td><td>${badge(p.status)}</td><td>${patientDue>0&&p.status!=='Đã thanh toán'?`<div><code>TA-DEMO-${p.id}</code><div class="subline">Mã thanh toán giả lập</div>${!isAdmin?`<button class="btn btn-primary btn-small" data-pay="${p.id}">Thanh toán demo</button>`:''}</div>`:patientDue===0?'Không cần trả':'—'}</td></tr>`;}),'Chưa có khoản thu'),'Mã thanh toán chỉ hiển thị khi số tiền bệnh nhân cần trả lớn hơn 0; mã chỉ dùng minh họa, không thể dùng để chuyển tiền.')}`;}
function renderStaff(){
 const rows=state.users.map(u=>{
  const action=u.id===currentUser.id?'<span class="muted">Đang đăng nhập</span>':(u.role==='patient'||u.role==='director'?'<span class="muted">—</span>':`<div class="inline-actions"><button class="btn ${u.active?'btn-danger':'btn-secondary'} btn-small" data-toggle-user="${u.id}">${u.active?'Khóa tài khoản':'Mở tài khoản'}</button><button class="btn btn-outline btn-small" data-delete-user="${u.id}">Xóa</button></div>`);
  return `<tr><td>${personCell(u.name,u.username)}</td><td>${esc(ROLE_LABELS[u.role])}</td><td>${esc(u.department)}</td><td>${badge(u.active?'Đang hoạt động':'Đã khóa')}</td><td>${action}</td></tr>`;
 });
 return `${welcome('Quản lý tài khoản','Admin có thể tạo, khóa hoặc mở tài khoản nhân viên y tế. Người tự đăng ký ngoài hệ thống chỉ được làm bệnh nhân.')}<div class="notice info">Tài khoản nhân viên được tạo tại đây; không cho đăng ký công khai các vai trò nội bộ.</div>${panel('Tạo tài khoản nhân viên y tế',`<form id="staff-form" class="field-grid"><div class="field"><label>Họ tên *</label><input name="name" required></div><div class="field"><label>Tên đăng nhập *</label><input name="username" minlength="4" required></div><div class="field"><label>Email *</label><input name="email" type="email" required></div><div class="field"><label>Bộ phận *</label><select name="role"><option value="doctor">Bác sĩ điều trị</option><option value="cls">Cận lâm sàng</option><option value="imaging">Bác sĩ chẩn đoán hình ảnh</option><option value="pharmacist">Dược sĩ</option><option value="physio">Kỹ thuật vật lý trị liệu</option><option value="finance">Tài chính</option><option value="tech">TECH</option></select></div><div class="field"><label>Mật khẩu cấp ban đầu *</label><input name="password" type="password" minlength="6" required value="Demo123!"></div><div class="field"><label>Phòng/khoa *</label><input name="department" required></div><div class="field full"><button class="btn btn-primary" type="submit">Tạo tài khoản nhân viên</button></div></form>`,'Chỉ Admin đang đăng nhập mới được tạo tài khoản')}${panel('Danh sách tài khoản',table(['TÀI KHOẢN','VAI TRÒ','BỘ PHẬN','TRẠNG THÁI','THAO TÁC'],rows,'Chưa có tài khoản'),'Quản lý nhân sự')}`;
}
function renderLogs(){const logs=state.logs;return `${welcome('Nhật ký hoạt động','Theo dõi thao tác demo được ghi nhận trên trình duyệt. TECH chỉ xem dữ liệu vận hành, không có bệnh án.')} ${panel('Nhật ký hệ thống',logsTable(logs),'Mới nhất ở đầu danh sách')}`;}
function logsTable(logs){return table(['NGƯỜI THỰC HIỆN','THAO TÁC','CHI TIẾT','THỜI GIAN'],logs.map(l=>`<tr><td>${personCell(userName(l.actorId),l.actorId?'Tài khoản nội bộ':'Hệ thống')}</td><td><strong>${esc(l.action)}</strong></td><td>${esc(l.detail)}</td><td>${fmtDate(l.createdAt)}</td></tr>`),'Chưa có nhật ký');}
function renderCLS(){return `${welcome('Chỉ định cận lâm sàng','Nhập kết quả chỉ định một lần. Sau khi gửi, nội dung bị khóa trong giao diện demo.')}<div class="notice warning">Chỉ sử dụng kết quả giả lập. Không nhập kết quả xét nghiệm của bệnh nhân thật.</div>${panel('Danh sách chỉ định',clsTable(state.clsOrders),'Chỉ định do bác sĩ tạo')}`;}
function clsTable(orders){return table(['CHỈ ĐỊNH','BỆNH NHÂN','BÁC SĨ','GHI CHÚ','KẾT QUẢ','THAO TÁC'],orders.map(o=>`<tr><td><strong>${esc(o.testName)}</strong><div class="subline">Mã chỉ định #${o.id} · ${fmtDate(o.createdAt)}</div></td><td>${esc(patientName(o.patientId))}</td><td>${esc(userName(o.doctorId))}</td><td>${esc(o.notes||'—')}</td><td>${o.result?`<strong>${esc(o.result)}</strong><div class="subline">Gửi ${fmtDate(o.resultAt)}</div>`:badge('Chờ kết quả')}</td><td>${o.result?'🔒 Đã khóa':`<button class="btn btn-primary btn-small" data-enter-cls="${o.id}">Nhập kết quả</button>`}</td></tr>`),'Chưa có chỉ định');}
function renderPharmacy(){const recs=state.records.filter(r=>r.prescription);return `${welcome('Đơn thuốc & báo cáo','Xem toa thuốc demo và gửi cảnh báo về vấn đề cần bác sĩ kiểm tra.')}<div class="notice warning">Nội dung toa thuốc chỉ dùng để minh họa giao diện, không được dùng để mua hoặc sử dụng thuốc.</div>${panel('Hồ sơ có toa thuốc',pharmacyTable(recs),'Gửi báo cáo nếu cần bác sĩ xem lại')}${panel('Báo cáo đã gửi',reportsTable(state.reports),'Trạng thái phản hồi từ bác sĩ')}`;}
function pharmacyTable(recs){return table(['BỆNH NHÂN / HỒ SƠ','BÁC SĨ','TOA THUỐC DEMO','THAO TÁC'],recs.map(r=>`<tr><td>${personCell(patientName(r.patientId),'Bệnh án #'+r.id)}</td><td>${esc(userName(r.doctorId))}</td><td>${esc(r.prescription)}</td><td><button class="btn btn-secondary btn-small" data-report-record="${r.id}">Báo cáo vấn đề</button></td></tr>`),'Chưa có hồ sơ có toa thuốc');}
function reportsTable(reports){return table(['MÃ BÁO CÁO','BỆNH ÁN','NỘI DUNG','TRẠNG THÁI','THỜI GIAN'],reports.map(r=>`<tr><td>#${r.id}</td><td>#${r.recordId} · ${esc(patientName(state.records.find(x=>x.id===r.recordId)?.patientId))}</td><td>${esc(r.message)}</td><td>${badge(r.status)}</td><td>${fmtDate(r.createdAt)}</td></tr>`),'Chưa có báo cáo');}
function renderReports(){return `${welcome('Báo cáo từ dược','Xem các báo cáo của dược sĩ và đánh dấu đã xem sau khi kiểm tra.')} ${panel('Báo cáo cần xử lý',table(['BÁO CÁO','BỆNH ÁN / BỆNH NHÂN','NỘI DUNG','TRẠNG THÁI','THAO TÁC'],state.reports.map(r=>`<tr><td>#${r.id}<div class="subline">${fmtDate(r.createdAt)}</div></td><td>#${r.recordId} · ${esc(patientName(state.records.find(x=>x.id===r.recordId)?.patientId))}</td><td>${esc(r.message)}</td><td>${badge(r.status)}</td><td>${r.status!=='Đã xem bởi bác sĩ'?`<button class="btn btn-secondary btn-small" data-resolve-report="${r.id}">Đánh dấu đã xem</button>`:'—'}</td></tr>`),'Không có báo cáo') ,'Báo cáo liên chuyên môn')}`;}
function renderPhysio(){
  const recs=state.records.filter(r=>r.plan);
  const body=recs.map(r=>`<div class="record-card"><div class="record-card-top"><div><h3>${esc(patientName(r.patientId))} · Bệnh án #${r.id}</h3><div class="record-meta">Bác sĩ: ${esc(userName(r.doctorId))} · ${fmtDate(r.updatedAt)}</div></div>${badge('Chỉ xem')}</div><p><strong>Chẩn đoán ghi trong demo:</strong> ${esc(r.diagnosis)}</p><p><strong>Kế hoạch:</strong> ${esc(r.plan)}</p></div>`).join('')||'<div class="empty-state">Chưa có kế hoạch điều trị.</div>';
  return `${welcome('Kế hoạch vật lý trị liệu','Xem hồ sơ có kế hoạch điều trị do bác sĩ ghi nhận.')}<div class="stats-grid">${statCard('♧','Kế hoạch',recs.length,'Hồ sơ có nội dung điều trị')}${statCard('♙','Bệnh nhân',new Set(recs.map(r=>r.patientId)).size,'Hồ sơ liên quan')}${statCard('◷','Cập nhật gần đây',recs.length?fmtDate(recs[0].updatedAt,false):'—','Dữ liệu demo')}${statCard('▤','Quyền truy cập','Chỉ xem','Không sửa bệnh án')}</div>${panel('Hồ sơ có kế hoạch điều trị',body,'Chỉ xem thông tin cần thiết')}`;
}
function renderFinance(){const paid=state.payments.filter(p=>p.status==='Đã thanh toán').reduce((s,p)=>s+p.amount,0);const unpaid=state.payments.filter(p=>p.status==='Chưa thanh toán').reduce((s,p)=>s+p.amount,0);return `${welcome('Quản lý tài chính','Cập nhật trạng thái khoản thu, bảo hiểm hoặc hỗ trợ tài chính trong dữ liệu demo.')}<div class="stats-grid">${statCard('₫','Đã thanh toán',money(paid),'Tổng khoản có trạng thái đã thanh toán')}${statCard('◷','Chưa thanh toán',money(unpaid),'Khoản cần theo dõi')}${statCard('▤','Tổng khoản thu',state.payments.length,'Tất cả trạng thái')}</div>${panel('Danh sách khoản thu',financeTable(state.payments.slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))),'Không phát sinh giao dịch tiền thật')}`;}
function financeTable(pays){return table(['BỆNH NHÂN','KHOẢN THU','SỐ TIỀN','TRẠNG THÁI','CẬP NHẬT'],pays.map(p=>`<tr><td>${personCell(patientName(p.patientId))}</td><td>${esc(p.description)}<div class="subline">${fmtDate(p.createdAt)}</div></td><td><strong>${money(p.amount)}</strong></td><td>${badge(p.status)}</td><td><select aria-label="Trạng thái khoản thu" data-finance-status="${p.id}" class="finance-select"><option ${p.status==='Chưa thanh toán'?'selected':''}>Chưa thanh toán</option><option ${p.status==='Đã thanh toán'?'selected':''}>Đã thanh toán</option><option ${p.status==='Chờ bảo hiểm'?'selected':''}>Chờ bảo hiểm</option><option ${p.status==='Hỗ trợ tài chính'?'selected':''}>Hỗ trợ tài chính</option></select></td></tr>`),'Chưa có khoản thu');}
function toggleModal(title,body,confirmText,onConfirm,danger=false){showModal(title,body,`<button class="btn btn-outline" id="modal-cancel">Hủy</button><button class="btn ${danger?'btn-danger':'btn-primary'}" id="modal-confirm">${confirmText}</button>`);document.getElementById('modal-cancel').onclick=closeModal;document.getElementById('modal-confirm').onclick=()=>{onConfirm();closeModal();};}
function editRecordModal(id){const r=state.records.find(x=>x.id===Number(id));if(!r)return;const within=Date.now()-new Date(r.createdAt).getTime()<=24*60*60*1000;if(!within){showToast('Đã quá 24 giờ, không thể chỉnh sửa hồ sơ demo.');return;}showModal('Chỉnh sửa bệnh án',`<form id="edit-record-form" class="field-grid"><div class="field full"><label>Chẩn đoán / ghi nhận *</label><textarea name="diagnosis" required>${esc(r.diagnosis)}</textarea></div><div class="field full"><label>Kế hoạch điều trị</label><textarea name="plan">${esc(r.plan)}</textarea></div><div class="field full"><label>Toa thuốc demo</label><textarea name="prescription">${esc(r.prescription)}</textarea></div><p class="helper-text field full">Chỉ được chỉnh sửa trong vòng 24 giờ tính từ thời điểm tạo hồ sơ.</p></form>`,`<button class="btn btn-outline" id="modal-cancel">Hủy</button><button class="btn btn-primary" id="modal-confirm">Lưu thay đổi</button>`);document.getElementById('modal-cancel').onclick=closeModal;document.getElementById('modal-confirm').onclick=()=>{const f=document.getElementById('edit-record-form');if(!f.reportValidity())return;const fd=new FormData(f);r.diagnosis=fd.get('diagnosis').trim();r.plan=fd.get('plan').trim();r.prescription=fd.get('prescription').trim();r.updatedAt=isoNow();saveState();logAction('Chỉnh sửa bệnh án',`Giám đốc chỉnh sửa bệnh án #${r.id} trong thời hạn 24 giờ`);closeModal();renderPage();showToast('Đã lưu thay đổi bệnh án demo.');};}
function reportModal(recordId){const r=state.records.find(x=>x.id===Number(recordId));if(!r)return;showModal('Báo cáo vấn đề toa thuốc',`<p>Bệnh nhân: <strong>${esc(patientName(r.patientId))}</strong> · Bệnh án #${r.id}</p><form id="report-form"><div class="field"><label>Nội dung cần bác sĩ xem lại *</label><textarea name="message" required placeholder="Nhập nội dung minh họa"></textarea></div></form>`,`<button class="btn btn-outline" id="modal-cancel">Hủy</button><button class="btn btn-primary" id="modal-confirm">Gửi báo cáo</button>`);document.getElementById('modal-cancel').onclick=closeModal;document.getElementById('modal-confirm').onclick=()=>{const f=document.getElementById('report-form');if(!f.reportValidity())return;const message=new FormData(f).get('message').trim();state.reports.unshift({id:nextId('report'),recordId:r.id,pharmacistId:currentUser.id,message,status:'Chờ bác sĩ phản hồi',createdAt:isoNow()});saveState();logAction('Báo cáo vấn đề toa thuốc',`Báo cáo liên quan bệnh án #${r.id}`);closeModal();renderPage();showToast('Đã gửi báo cáo demo cho bác sĩ.');};}
function clsModal(id){const o=state.clsOrders.find(x=>x.id===Number(id));if(!o)return;if(o.result){showToast('Kết quả đã gửi và đang bị khóa.');return;}showModal('Nhập kết quả cận lâm sàng',`<p><strong>${esc(o.testName)}</strong> · Bệnh nhân: ${esc(patientName(o.patientId))}</p><form id="cls-form"><div class="field"><label>Kết quả (giả lập) *</label><textarea name="result" required placeholder="Nhập kết quả minh họa, không dùng kết quả thật"></textarea></div></form>`,`<button class="btn btn-outline" id="modal-cancel">Hủy</button><button class="btn btn-primary" id="modal-confirm">Gửi kết quả một lần</button>`);document.getElementById('modal-cancel').onclick=closeModal;document.getElementById('modal-confirm').onclick=()=>{const f=document.getElementById('cls-form');if(!f.reportValidity())return;const result=new FormData(f).get('result').trim();if(o.result){showToast('Kết quả đã gửi.');closeModal();return;}o.result=result;o.resultBy=currentUser.id;o.resultAt=isoNow();saveState();logAction('Nhập kết quả CLS',`Đã gửi kết quả CLS cho chỉ định #${o.id}`);closeModal();renderPage();showToast('Đã gửi kết quả CLS. Nội dung bị khóa trong demo.');};}
function payModal(id){const p=state.payments.find(x=>x.id===Number(id)&&x.patientId===currentUser.id);if(!p)return;showModal('Thanh toán mô phỏng',`<div class="notice warning">Đây chỉ là thao tác demo. Không có tiền thật được chuyển.</div><p>Khoản thu: <strong>${esc(p.description)}</strong></p><p>Số tiền hiển thị: <strong>${money(p.amount)}</strong></p><form id="pay-form"><div class="field"><label>Phương thức mô phỏng</label><select name="method"><option>Ví điện tử mô phỏng</option><option>Chuyển khoản demo</option><option>Tiền mặt demo</option></select></div></form>`,`<button class="btn btn-outline" id="modal-cancel">Hủy</button><button class="btn btn-primary" id="modal-confirm">Xác nhận demo</button>`);document.getElementById('modal-cancel').onclick=closeModal;document.getElementById('modal-confirm').onclick=()=>{p.status='Đã thanh toán';p.method=new FormData(document.getElementById('pay-form')).get('method');p.paidAt=isoNow();saveState();logAction('Thanh toán mô phỏng',`Thanh toán khoản #${p.id} bằng ${p.method}`);closeModal();renderPage();showToast('Đã cập nhật trạng thái thanh toán demo. Không có tiền thật được chuyển.');};}
function suggestedDepartment(text){const t=text.toLocaleLowerCase('vi');const groups={'Tim mạch':['đau ngực','hồi hộp','tim đập','khó thở'],'Tai Mũi Họng':['đau họng','nghẹt mũi','sổ mũi','đau tai'],'Tiêu hóa':['đau bụng','buồn nôn','tiêu chảy','táo bón'],'Cơ xương khớp':['đau lưng','đau khớp','đau cổ','đau vai'],'Da liễu':['phát ban','nổi mẩn','ngứa','mụn']};for(const [dept,words] of Object.entries(groups)){if(words.some(w=>t.includes(w)))return dept;}return 'Nội tổng quát';}

function exportSymptomsPdf(){const field=document.querySelector('#booking-form [name="symptoms"]');const content=(field?.value||'').trim();if(!content){showToast('Hãy nhập triệu chứng trước khi xuất phiếu.');return;}const visit=visitMode==='revisit'?'Tái khám':'Khám bệnh mới';const suggestion=suggestedDepartment(content);const w=window.open('','_blank','width=800,height=700');if(!w){showToast('Trình duyệt đang chặn cửa sổ in. Hãy cho phép cửa sổ bật lên rồi thử lại.');return;}w.document.write(`<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Phiếu triệu chứng - Tâm An</title><style>body{font-family:Arial,sans-serif;max-width:760px;margin:36px auto;color:#222;line-height:1.6}h1{text-align:center}.box{border:1px solid #bbb;padding:16px;border-radius:8px;white-space:pre-wrap}small{color:#666}</style></head><body><h1>PHIẾU GHI NHẬN TRIỆU CHỨNG</h1><p><strong>Cơ sở:</strong> Phòng khám Tâm An (bản demo)</p><p><strong>Người bệnh:</strong> ${esc(currentUser.name)}</p><p><strong>Loại lượt khám:</strong> ${esc(visit)}</p><p><strong>Thời gian xuất phiếu:</strong> ${esc(fmtDate(isoNow()))}</p><p><strong>Triệu chứng:</strong></p><div class="box">${esc(content)}</div><p><strong>Khoa gợi ý theo từ khóa demo:</strong> ${esc(suggestion)}</p><p><small>Phiếu mô phỏng; không phải chẩn đoán y khoa.</small></p><button onclick="window.print()">In / Lưu thành PDF</button><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close();logAction('Xuất phiếu triệu chứng',`Xuất phiếu triệu chứng lượt ${visit}`);}

// Event handling is delegated so navigation and tables continue working after re-render.
document.addEventListener('click',e=>{
 const exportBtn=e.target.closest('[data-export-symptoms]');if(exportBtn){exportSymptomsPdf();return;}
 const visit=e.target.closest('[data-visit-mode]');if(visit){visitMode=visit.dataset.visitMode||null;navTo('appointments');return;}
 const nav=e.target.closest('[data-page]');if(nav){navTo(nav.dataset.page);return;}
 const cancel=e.target.closest('[data-cancel-appt]');if(cancel){const a=state.appointments.find(x=>x.id===Number(cancel.dataset.cancelAppt));if(!a)return;const hours=(new Date(a.at)-Date.now())/36e5;if(hours<24){showToast('Chỉ được hủy lịch trước giờ khám ít nhất 24 giờ.');return;}toggleModal('Hủy lịch khám',`<p>Bạn có chắc muốn hủy lịch khám <strong>${esc(a.department)}</strong> vào ${fmtDate(a.at)}?</p>`,'Xác nhận hủy',()=>{a.status='Đã hủy';saveState();logAction('Hủy lịch khám',`Bệnh nhân hủy lịch #${a.id}`);renderPage();showToast('Đã hủy lịch demo.');},true);return;}
 const apptAction=e.target.closest('[data-appt-action]');if(apptAction){const a=state.appointments.find(x=>x.id===Number(apptAction.dataset.id));if(!a)return;toggleModal('Cập nhật lịch khám',`<p>Xác nhận cập nhật lịch #${a.id} thành trạng thái <strong>${apptAction.dataset.apptAction==='complete'?'Đã hoàn tất':'Đã hủy'}</strong>?</p>`,'Xác nhận',()=>{a.status=apptAction.dataset.apptAction==='complete'?'Đã hoàn tất':'Đã hủy';saveState();logAction('Cập nhật lịch khám',`Lịch #${a.id}: ${a.status}`);renderPage();showToast('Đã cập nhật lịch khám.');});return;}
 const edit=e.target.closest('[data-edit-record]');if(edit){editRecordModal(edit.dataset.editRecord);return;}
 const report=e.target.closest('[data-report-record]');if(report){reportModal(report.dataset.reportRecord);return;}
 const cls=e.target.closest('[data-enter-cls]');if(cls){clsModal(cls.dataset.enterCls);return;}
 const pay=e.target.closest('[data-pay]');if(pay){payModal(pay.dataset.pay);return;}
 const toggle=e.target.closest('[data-toggle-user]');if(toggle){const u=state.users.find(x=>x.id===Number(toggle.dataset.toggleUser));if(!u)return;toggleModal(u.active?'Khóa tài khoản':'Mở tài khoản',`<p>${u.active?'Bạn muốn khóa':'Bạn muốn mở lại'} tài khoản <strong>${esc(u.username)}</strong> (${esc(u.name)})?</p>` ,u.active?'Khóa tài khoản':'Mở tài khoản',()=>{u.active=!u.active;saveState();logAction('Quản lý tài khoản nhân viên',`Tài khoản ${u.username} chuyển active=${u.active}`);renderPage();showToast('Đã cập nhật trạng thái tài khoản.');},u.active);return;}
 const delUser=e.target.closest('[data-delete-user]');if(delUser){const u=state.users.find(x=>x.id===Number(delUser.dataset.deleteUser));if(!u||u.role==='patient'||u.role==='director'||u.id===currentUser.id){showToast('Chỉ có thể xóa tài khoản nhân viên y tế khác.');return;}toggleModal('Xóa tài khoản nhân viên',`<p>Bạn có chắc muốn xóa tài khoản <strong>${esc(u.username)}</strong> (${esc(u.name)})? Các lịch sử đã phát sinh sẽ vẫn được giữ lại trong dữ liệu demo.</p>`,'Xóa tài khoản',()=>{state.users=state.users.filter(x=>x.id!==u.id);saveState();logAction('Xóa tài khoản nhân viên',`Đã xóa tài khoản ${u.username}`);renderPage();showToast('Đã xóa tài khoản nhân viên khỏi demo.');},true);return;}
 const resolve=e.target.closest('[data-resolve-report]');if(resolve){const r=state.reports.find(x=>x.id===Number(resolve.dataset.resolveReport));if(r){r.status='Đã xem bởi bác sĩ';saveState();logAction('Xử lý báo cáo dược',`Bác sĩ đã xem báo cáo #${r.id}`);renderPage();showToast('Đã đánh dấu báo cáo đã xem.');}return;}
});

document.addEventListener('submit',e=>{
 if(e.target.id==='register-form'){e.preventDefault();const fd=new FormData(e.target);const name=fd.get('name').trim(),email=fd.get('email').trim().toLowerCase(),password=fd.get('password'),password2=fd.get('password2');const err=document.getElementById('register-error');err.textContent='';if(password.length<6||!/[0-9]/.test(password)||!/[!@#$%^&*(),.?":{}|<>_\-]/.test(password)){err.textContent='Mật khẩu cần ít nhất 6 ký tự, có 1 chữ số và 1 ký tự đặc biệt.';return;}if(password!==password2){err.textContent='Mật khẩu nhập lại không khớp.';return;}if(state.users.some(u=>(u.email||'').toLowerCase()===email)){err.textContent='Email đã được sử dụng.';return;}const base=(email.split('@')[0]||'benhnhan').toLowerCase().replace(/[^a-z0-9._-]/g,'')||'benhnhan';let username=base,n=2;while(state.users.some(u=>u.username.toLowerCase()===username.toLowerCase())){username=base+n++;}const u={id:nextId('user'),username,password,name,email,role:'patient',department:'Bệnh nhân',phone:'',active:true,profile:null};state.users.push(u);saveState();document.getElementById('register-backdrop').classList.add('hidden');document.getElementById('login-user').value=email;document.getElementById('login-password').value='';showToast('Đăng ký thành công. Tên đăng nhập được tạo tự động từ email. Hãy đăng nhập để cập nhật hồ sơ bệnh nhân.');return;}
 if(e.target.id==='patient-profile-form'){e.preventDefault();const fd=new FormData(e.target);const profile={phone:fd.get('phone').trim(),cccd:fd.get('cccd').trim(),bhyt:fd.get('bhyt').trim(),dob:fd.get('dob'),gender:fd.get('gender'),address:fd.get('address').trim(),height:fd.get('height'),weight:fd.get('weight'),foodAllergies:fd.get('foodAllergies').trim(),drugAllergies:fd.get('drugAllergies').trim(),history:fd.get('history').trim(),updatedAt:isoNow()};if(!profile.phone||!profile.cccd||!profile.bhyt||!profile.dob||!profile.gender||!profile.address||!profile.height||!profile.weight){showToast('Vui lòng hoàn tất các trường bắt buộc.');return;}const user=state.users.find(u=>u.id===currentUser.id);user.profile=profile;user.phone=profile.phone;currentUser=clone(user);saveState();logAction('Cập nhật hồ sơ bệnh nhân','Đã lưu thông tin hồ sơ bắt buộc');visitMode=null;currentPage='appointments';workspaceScreen();showToast('Đã lưu hồ sơ. Hãy chọn khám mới hoặc tái khám.');return;}
 if(e.target.id==='staff-form'){e.preventDefault();if(currentUser.role!=='director'){showToast('Chỉ Admin được tạo tài khoản nhân viên.');return;}const fd=new FormData(e.target);const username=fd.get('username').trim();const email=fd.get('email').trim().toLowerCase();if(state.users.some(u=>u.username.toLowerCase()===username.toLowerCase())){showToast('Tên đăng nhập đã tồn tại.');return;}if(state.users.some(u=>(u.email||'').toLowerCase()===email)){showToast('Email đã tồn tại.');return;}const role=fd.get('role');const u={id:nextId('user'),username,password:fd.get('password'),name:fd.get('name').trim(),email,role,department:fd.get('department').trim(),phone:'',active:true,profile:null};state.users.push(u);saveState();logAction('Admin tạo tài khoản nhân viên',`Tạo tài khoản ${username} (${ROLE_LABELS[role]})`);renderPage();showToast('Đã tạo tài khoản nhân viên.');return;}
 if(e.target.id==='login-form'){e.preventDefault();const username=document.getElementById('login-user').value.trim();const password=document.getElementById('login-password').value;const user=state.users.find(u=>(u.username.toLowerCase()===username.toLowerCase()||(u.email||'').toLowerCase()===username.toLowerCase())&&u.password===password&&u.active);if(!user){document.getElementById('login-error').textContent='Tài khoản hoặc mật khẩu không đúng, hoặc tài khoản đã bị khóa.';return;}currentUser=clone(user);visitMode=null;currentPage=user.role==='patient'?(user.profile?'appointments':'profile'):'overview';logAction('Đăng nhập','Đăng nhập thành công');workspaceScreen();return;}
 if(e.target.id==='booking-form'){e.preventDefault();const fd=new FormData(e.target);const at=new Date(fd.get('at'));if(Number.isNaN(at.getTime())||at<=new Date()){showToast('Vui lòng chọn ngày giờ trong tương lai.');return;}const symptomText=fd.get('symptoms').trim();if(!symptomText){showToast('Vui lòng nhập triệu chứng giả lập.');return;}const suggestion=suggestedDepartment(symptomText);const department=fd.get('department');const doctorId=Number(fd.get('doctorId'));const appt={id:nextId('appointment'),patientId:currentUser.id,doctorId,department,at:at.toISOString(),location:fd.get('location'),visitType:fd.get('visitType'),reason:(fd.get('visitType')==='revisit'?'Tái khám. ':'Khám mới. ')+symptomText+(fd.get('reason').trim()?' — '+fd.get('reason').trim():''),status:'Đã đặt',createdAt:isoNow()};state.appointments.push(appt);state.symptoms.push({id:nextId('symptom'),patientId:currentUser.id,content:symptomText,department:suggestion,visitType:fd.get('visitType'),createdAt:isoNow()});state.payments.push({id:nextId('payment'),patientId:currentUser.id,appointmentId:appt.id,description:'Phí khám '+department,amount:200000,insuranceCoverage:0,patientDue:200000,status:'Chưa thanh toán',method:'',createdAt:isoNow(),paidAt:null});saveState();logAction('Đặt lịch khám',`Đã tạo lịch ${appt.visitType==='revisit'?'tái khám':'khám mới'} khoa ${department}; gợi ý từ khóa: ${suggestion}`);visitMode=null;navTo('appointments');showToast('Đã lưu triệu chứng và đặt lịch demo thành công.');return;}
 if(e.target.id==='symptom-form'){e.preventDefault();if(state.symptoms.some(s=>s.patientId===currentUser.id)){showToast('Triệu chứng đã được ghi nhận một lần trong demo.');return;}const content=new FormData(e.target).get('content').trim();if(!content)return;const department=suggestedDepartment(content);state.symptoms.push({id:nextId('symptom'),patientId:currentUser.id,content,department,createdAt:isoNow()});saveState();logAction('Ghi triệu chứng',`Hệ thống gợi ý khoa demo: ${department}`);renderPage();showToast('Đã lưu triệu chứng demo. Gợi ý khoa không phải chẩn đoán.');return;}
 if(e.target.id==='record-form'){e.preventDefault();const fd=new FormData(e.target);const patientId=Number(fd.get('patientId'));const diagnosis=fd.get('diagnosis').trim();if(!patientId||!diagnosis){showToast('Hãy chọn bệnh nhân và nhập chẩn đoán demo.');return;}const record={id:nextId('record'),patientId,doctorId:currentUser.id,appointmentId:fd.get('appointmentId')?Number(fd.get('appointmentId')):null,symptoms:fd.get('symptoms').trim(),physicalSigns:(fd.get('physicalSigns')||'').trim(),preliminaryDiagnosis:(fd.get('preliminaryDiagnosis')||'').trim(),diagnosis, treatmentType:fd.get('treatmentType')||'medicine',plan:fd.get('plan').trim(),prescription:fd.get('prescription').trim(),followUpDate:fd.get('followUpDate')||'',createdAt:isoNow(),updatedAt:isoNow()};state.records.unshift(record);const testName=fd.get('testName').trim();if(testName)state.clsOrders.push({id:nextId('clsOrder'),recordId:record.id,patientId,doctorId:currentUser.id,testName,notes:fd.get('testNotes').trim(),result:null,resultBy:null,resultAt:null,createdAt:isoNow()});saveState();logAction('Tạo bệnh án',`Bác sĩ tạo bệnh án #${record.id}`);renderPage();showToast(testName?'Đã lưu bệnh án và chỉ định CLS demo.':'Đã lưu bệnh án demo.');return;}
});

document.addEventListener('input',e=>{if(e.target.name==='symptoms'){const out=document.getElementById('department-suggestion');const sel=document.getElementById('booking-department');if(out&&sel){const dep=suggestedDepartment(e.target.value);out.textContent=e.target.value.trim()?'Gợi ý theo từ khóa: '+dep+' — bạn có thể tự chọn khoa khác.':'Nhập triệu chứng để xem gợi ý khoa.';if(e.target.value.trim())sel.value=dep;}}});
document.addEventListener('change',e=>{
 const sel=e.target.closest('[data-finance-status]');if(sel){const p=state.payments.find(x=>x.id===Number(sel.dataset.financeStatus));if(!p)return;const old=p.status;p.status=sel.value;if(p.status==='Đã thanh toán')p.paidAt=isoNow();saveState();logAction('Cập nhật thanh toán',`Khoản #${p.id}: ${old} → ${p.status}`);renderPage();showToast('Đã cập nhật trạng thái tài chính demo.');}
});

document.getElementById('show-register').addEventListener('click',()=>{document.getElementById('register-error').textContent='';document.getElementById('register-backdrop').classList.remove('hidden');});
document.getElementById('register-close').addEventListener('click',()=>document.getElementById('register-backdrop').classList.add('hidden'));
document.getElementById('register-backdrop').addEventListener('click',e=>{if(e.target.id==='register-backdrop')e.currentTarget.classList.add('hidden');});
document.getElementById('toggle-password').addEventListener('click',()=>{const input=document.getElementById('login-password');input.type=input.type==='password'?'text':'password';document.getElementById('toggle-password').textContent=input.type==='password'?'Hiện':'Ẩn';});
document.getElementById('reset-data').addEventListener('click',()=>{toggleModal('Khôi phục dữ liệu demo','<p>Thao tác này sẽ xóa các thay đổi được lưu trong trình duyệt và khôi phục dữ liệu minh họa ban đầu.</p>','Khôi phục',()=>{state=initialState();saveState();currentUser=null;loginScreen();showToast('Đã khôi phục dữ liệu demo.');},true);});
document.getElementById('logout-button').addEventListener('click',()=>{if(currentUser)logAction('Đăng xuất','Người dùng đăng xuất');currentUser=null;currentPage='overview';document.getElementById('profile-menu').classList.add('hidden');loginScreen();});
document.getElementById('profile-chip').addEventListener('click',()=>document.getElementById('profile-menu').classList.toggle('hidden'));
document.getElementById('mobile-menu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('modal-close').addEventListener('click',closeModal);
document.getElementById('modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});

// Startup validation: make sure every role can be selected, then show the login page.
if(!state.users||!state.users.length){state=initialState();saveState();}
loginScreen();
